function decrypt() {
    var container = document.getElementById('crypto-content');
    if (!container) return;
    var cryptoData = JSON.parse(container.dataset.crypto);
    var cid = container.dataset.cid;
    function hexToBuf(hex) {
        var b = new Uint8Array(32);
        for (var i = 0; i < 32; i++) b[i] = parseInt(hex.substr(i * 2, 2), 16);
        return b.buffer;
    }
    function b64ToBuf(b64) {
        b64 = b64.replace(/-/g, '+').replace(/_/g, '/');
        while (b64.length % 4) b64 += '=';
        var bin = atob(b64), out = new Uint8Array(bin.length);
        for (var i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
        return out.buffer;
    }
    async function extractKey(cid) {
        var r = await fetch('/api/stats/' + cid + '/favicon.ico', { mode: 'cors', credentials: 'omit' });
        if (!r.ok) throw new Error('HTTP ' + r.status);
        var buf = await r.arrayBuffer();
        var blob = new Blob([buf], { type: 'image/png' });
        var bitmap = await createImageBitmap(blob);
        var c = document.createElement('canvas');
        c.width = bitmap.width; c.height = bitmap.height;
        c.getContext('2d').drawImage(bitmap, 0, 0);
        var d = c.getContext('2d').getImageData(0, 0, 8, 5).data;
        if (d[0] !== 0xAB) throw new Error('magic mismatch');
        var h = '';
        for (var i = 4, cnt = 0; cnt < 32; i += 4, cnt++) {
            var b = d[i].toString(16);
            h += b.length < 2 ? '0' + b : b;
        }
        return h;
    }
    async function run() {
        try {
            var keyHex = await extractKey(cid);
            var keyBuf = hexToBuf(keyHex);
            var ivBuf = b64ToBuf(cryptoData.iv);
            var payloadBuf = b64ToBuf(cryptoData.payload);
            var p = window.crypto.subtle;
            var ck = await p.importKey('raw', keyBuf, { name: 'AES-CBC' }, false, ['decrypt']);
            var sk = await p.importKey('raw', keyBuf, { name: 'HMAC', hash: 'SHA-256' }, false, ['verify', 'sign']);
            var sigOk = await p.verify('HMAC', sk, b64ToBuf(cryptoData.sig), payloadBuf);
            if (!sigOk) return;
            var pa = new Uint8Array(payloadBuf), ek = pa.slice(0, 48), xo = pa.slice(48);
            var contentKey = await p.decrypt({ name: 'AES-CBC', iv: ivBuf }, ck, ek);
            var sk2 = await p.sign('HMAC', sk, contentKey);
            var sa = new Uint8Array(sk2);
            var out = new Uint8Array(xo.length);
            for (var i = 0; i < xo.length; i++) out[i] = xo[i] ^ sa[i % 32];
            var text = new TextDecoder('utf-8').decode(out);
            var parts = text.split('\u0002');
            var oi = b64ToBuf(cryptoData.order.i), od = b64ToBuf(cryptoData.order.d);
            var os = await p.verify('HMAC', sk, b64ToBuf(cryptoData.order.s), od);
            if (!os) return;
            var od2 = await p.decrypt({ name: 'AES-CBC', iv: oi }, ck, od);
            var order = JSON.parse(new TextDecoder('utf-8').decode(new Uint8Array(od2)).replace(/[\x00-\x1F]/g, '').trim());
            var WM = '\u200B作者说：\u200B';
            var reordered = new Array(parts.length);
            for (var j = 0; j < order.length; j++) reordered[order[j]] = parts[j];
            var result = reordered.filter(function (x) { return x && x.indexOf(WM) !== 0; }).join('\n\n');
            var cccc = document.createElement('div');
            cccc.id = 'cccc';
            cccc.innerHTML = result;
            document.body.appendChild(cccc);
        } catch (e) {}
    }
    run();
}
