@js:result=(function(){
  var d=(typeof result==='string')?JSON.parse(result):result;
  var data=d.data||d;
  var out=[];
  if(data.episodes&&data.episodes.length>0){
    for(var i=0;i<data.episodes.length;i++){
      var e=data.episodes[i];
      out.push({title:e.title||('第'+(e.episodeNo||(i+1))+'集'),url:'https://mdcmai4.xyz/api/v1/m3u8/proxy?path='+encodeURIComponent(e.videoUrl||'')});
    }
  }else if(data.videoUrl){
    out.push({title:data.title||'',url:'https://mdcmai4.xyz/api/v1/m3u8/proxy?path='+encodeURIComponent(data.videoUrl)});
  }
  return out;
})()

