var QQ_GROUP = "1097919737";
function login(){
  try{ java.upLoginData(); }catch(e){}
  java.toast("无需登录，直接使用");
}
function joinQQGroup(){
  var u = "mqqapi://card/show_pslcard?src_type=internal&version=1&card_type=group&uin=" + QQ_GROUP;
  try{
    java.openUrl(u);
    java.toast("已尝试打开QQ，若未跳转请手动搜索群号 " + QQ_GROUP);
  }catch(e){ java.longToast("请手动在QQ中搜索群号 " + QQ_GROUP); }
}

